    SECTION .Can_BitSearch_asm:CODE:NOROOT(2)

    PUBLIC Can_BitSearch
    
    THUMB

Can_BitSearch:

    CLZ R0,R0  ; Count the number of leading zeros in R0 (parameter value) and return the result (R0).
    BX LR      ; Branch back to address in LR and exchange instruction set.

    END
